/* From Uiverse.io by Mike11jr - Tags: loader */
.__UIV_SCOPE__ .spinner {
 flex-direction: row;
 display: flex;
 align-items: center;
 justify-content: center;
}

.__UIV_SCOPE__ .dot1, .__UIV_SCOPE__ .dot2, .__UIV_SCOPE__ .dot3 {
 width: 15px;
 height: 15px;
 border: double;
 border-color: white;
 border-radius: 50%;
 margin: 10px;
}

.__UIV_SCOPE__ .dot1 {
 animation: jump765 1.6s -0.32s linear infinite;
 background: #2495ff;
}

.__UIV_SCOPE__ .dot2 {
 animation: jump765 1.6s -0.16s linear infinite;
 background: #2495ff;
}

.__UIV_SCOPE__ .dot3 {
 animation: jump765 1.6s linear infinite;
 background: #2495ff;
}

@keyframes jump765 {
 0%, 80%, 100% {
  -webkit-transform: scale(0);
  transform: scale(0);
 }

 40% {
  -webkit-transform: scale(2.0);
  transform: scale(2.0);
 }
}
